import json, openpyxl
from pathlib import Path
m=json.loads(Path('inputs/manifest.json').read_text())
print('manifest keys', list(m)[:20])
print(json.dumps(m, ensure_ascii=False)[:2000])
# find delivery.xlsx
paths=[]
for k,v in m.items():
    if isinstance(v,list):
        for x in v:
            if isinstance(x,dict):
                s=json.dumps(x,ensure_ascii=False)
                if 'delivery.xlsx' in s:
                    print('entry',k,json.dumps(x,ensure_ascii=False)[:1000])
                    for kk in ('path','file_path','local_path','stored_path'):
                        if kk in x: paths.append(x[kk])
for p in paths[:3]:
    print('PATH',p,Path(p).exists())
    wb=openpyxl.load_workbook(p, data_only=False)
    for sn in wb.sheetnames:
        ws=wb[sn]
        print('SHEET',sn,ws.max_row,ws.max_column)
        for r in range(1,min(ws.max_row,14)+1):
            c=ws.cell(r,1)
            c2=ws.cell(r,2)
            print('row',r,'A',repr(c.value),c.data_type,c.number_format,'B',repr(c2.value),c2.data_type,c2.number_format)
        if sn=='Material':
            print('col widths', {k:v.width for k,v in ws.column_dimensions.items()})

